namespace FolderScope {
 public class OptionsForm:Form {
  public AppSettings Result;private Dictionary<string,Control> inputs=new Dictionary<string,Control>();private RuleEditor rules;
  public OptionsForm(AppSettings current,bool filterOnly){Result=UI.Clone(current);Text=L.T(filterOnly?"Scan Filter":"Options");Size=new Size(920,690);MinimumSize=new Size(800,580);Font=new Font("Segoe UI",9);AutoScaleDimensions=new SizeF(96,96);AutoScaleMode=AutoScaleMode.Dpi;StartPosition=FormStartPosition.CenterParent;var tabs=new TabControl{Dock=DockStyle.Fill};
   if(!filterOnly){var general=Page(tabs,"General");Combo(general,"Interface language",new[]{"简体中文","English"},Result.Language=="en-US"?"English":"简体中文");Combo(general,"Theme",new[]{"Light (Blue)","Dark (Blue)","Light (Red)","Light (Green)","Light (Orange)","Light (Purple)"},Result.Theme);Check(general,"Show welcome at startup",Result.Welcome);}
   var scan=Page(tabs,"Scanning");Number(scan,"Worker threads",Result.Scan.Threads,1,32);Check(scan,"Use NTFS MFT direct read (requires administrator)",Result.Scan.UseMft);Check(scan,"Collect file owners (slower)",Result.Scan.ReadOwners);Check(scan,"Skip hidden items",Result.Scan.SkipHidden);Check(scan,"Skip system items",Result.Scan.SkipSystem);TextInput(scan,"Include file patterns",Result.Scan.Include,false);TextInput(scan,"Exclude file patterns",Result.Scan.Exclude,false);TextInput(scan,"Exclude folder patterns",Result.Scan.ExcludeFolders,false);Number(scan,"Minimum size (bytes)",Result.Scan.MinimumSize,0,decimal.MaxValue);Number(scan,"Maximum size (0 = unlimited)",Result.Scan.MaximumSize,0,decimal.MaxValue);Number(scan,"Maximum depth (0 = unlimited)",Result.Scan.MaximumDepth,0,10000);scan.Controls.Add(new Label{Text=L.T("Use ; to separate wildcard patterns."),AutoSize=true});scan.Controls.Add(new Label{Text=L.T("Reparse points are skipped; all skips and errors are recorded."),AutoSize=true});
   var rp=new TabPage(L.T("Advanced rules"));rules=new RuleEditor(Result.Scan.Rules);rp.Controls.Add(rules);tabs.TabPages.Add(rp);
   if(!filterOnly){var mail=Page(tabs,"Email");TextInput(mail,"SMTP host",Result.SmtpHost,false);Number(mail,"Port",Result.SmtpPort,1,65535);Check(mail,"TLS / SSL",Result.SmtpSsl);TextInput(mail,"Username",Result.SmtpUser,false);TextInput(mail,"Password",Result.Password,true);TextInput(mail,"From address",Result.MailFrom,false);TextInput(mail,"Recipients (; separated)",Result.MailTo,false);mail.Controls.Add(new Label{Text=L.T("Passwords are protected by Windows for this user."),AutoSize=true});}
   var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=49,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(6)};var ok=UI.Button("OK",()=>{Read(filterOnly);DialogResult=DialogResult.OK;Close();});var cancel=UI.Button("Cancel",()=>Close());bottom.Controls.Add(cancel);bottom.Controls.Add(ok);Controls.Add(tabs);Controls.Add(bottom);AcceptButton=ok;CancelButton=cancel;Palette.Apply(this);
  }
  private TableLayoutPanel Page(TabControl tabs,string name){var tab=new TabPage(L.T(name)){AutoScroll=true};var table=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,Padding=new Padding(18),ColumnCount=2};table.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,280));table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));tab.Controls.Add(table);tabs.TabPages.Add(tab);return table;}
  private void Add(TableLayoutPanel p,string name,Control c){int row=p.RowCount++;p.RowStyles.Add(new RowStyle(SizeType.Absolute,38));var label=new Label{Text=L.T(name),Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft};c.Dock=DockStyle.Fill;c.Margin=new Padding(4,6,4,6);p.Controls.Add(label,0,row);p.Controls.Add(c,1,row);inputs[name]=c;}
  private void Combo(TableLayoutPanel p,string key,string[] options,string value){var c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};c.Items.AddRange(options);L.TranslateCombo(c);c.SelectedItem=value;Add(p,key,c);}
  private void TextInput(TableLayoutPanel p,string key,string value,bool password){Add(p,key,new TextBox{Text=value,UseSystemPasswordChar=password});}
  private void Number(TableLayoutPanel p,string key,decimal value,decimal min,decimal max){Add(p,key,new NumericUpDown{Minimum=min,Maximum=max,Value=Math.Max(min,Math.Min(max,value)),ThousandsSeparator=true});}
  private void Check(TableLayoutPanel p,string key,bool value){Add(p,key,new CheckBox{Checked=value});}
  private string S(string k){return inputs[k].Text;}private bool B(string k){return ((CheckBox)inputs[k]).Checked;}private long N(string k){return (long)((NumericUpDown)inputs[k]).Value;}
  private void Read(bool filterOnly){Result.Scan.Threads=(int)N("Worker threads");Result.Scan.ReadOwners=B("Collect file owners (slower)");Result.Scan.UseMft=B("Use NTFS MFT direct read (requires administrator)");Result.Scan.SkipHidden=B("Skip hidden items");Result.Scan.SkipSystem=B("Skip system items");Result.Scan.Include=S("Include file patterns");Result.Scan.Exclude=S("Exclude file patterns");Result.Scan.ExcludeFolders=S("Exclude folder patterns");Result.Scan.MinimumSize=N("Minimum size (bytes)");Result.Scan.MaximumSize=N("Maximum size (0 = unlimited)");Result.Scan.MaximumDepth=(int)N("Maximum depth (0 = unlimited)");Result.Scan.Rules=rules.Read();if(!filterOnly){Result.Language=(string)((ComboBox)inputs["Interface language"]).SelectedItem=="English"?"en-US":"zh-CN";Result.Theme=Convert.ToString(((ComboBox)inputs["Theme"]).SelectedItem);Result.Welcome=B("Show welcome at startup");Result.SmtpHost=S("SMTP host");Result.SmtpPort=(int)N("Port");Result.SmtpSsl=B("TLS / SSL");Result.SmtpUser=S("Username");Result.Password=S("Password");Result.MailFrom=S("From address");Result.MailTo=S("Recipients (; separated)");}}
 }
 public class ScheduleForm:Form {
  private AppSettings settings;private TextBox name,paths,output;private ComboBox report,format,frequency;private DateTimePicker start;private CheckBox email;private Label status;
  public ScheduleForm(AppSettings options,string current){settings=options;Text=L.T("Task Scheduler");Size=new Size(780,650);MinimumSize=new Size(700,600);Font=new Font("Segoe UI",9);AutoScaleDimensions=new SizeF(96,96);AutoScaleMode=AutoScaleMode.Dpi;StartPosition=FormStartPosition.CenterParent;var table=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18),ColumnCount=2,AutoScroll=true};table.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,210));table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Action<string,Control,int> add=(caption,control,height)=>{int r=table.RowCount++;table.RowStyles.Add(new RowStyle(SizeType.Absolute,height));table.Controls.Add(new Label{Text=L.T(caption),Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft},0,r);control.Dock=DockStyle.Fill;control.Margin=new Padding(4,6,4,6);table.Controls.Add(control,1,r);};
   name=new TextBox{Text=L.Chinese?"每日磁盘报告":"Daily disk report"};paths=new TextBox{Multiline=true,Text=current,ScrollBars=ScrollBars.Vertical};output=new TextBox{Text=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"FolderScope Reports")};report=Combo(new[]{"Folder details","Snapshot"}.Concat(Reports.Names).ToArray());format=Combo(new[]{"html","xlsx","csv","pdf","xml","txt"});frequency=Combo(new[]{"Daily","Weekly","Once"});start=new DateTimePicker{Format=DateTimePickerFormat.Custom,CustomFormat="yyyy-MM-dd HH:mm:ss",Value=DateTime.Now.AddHours(1)};email=new CheckBox{Text=L.T("Email report after completion")};add("Job name",name,40);add("Scan paths (one per line)",paths,105);add("Output folder",output,40);add("Report",report,40);add("Format",format,40);add("Frequency",frequency,40);add("Start time",start,40);add("Email",email,40);
   var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=95,Padding=new Padding(8)};buttons.Controls.Add(UI.Button("Create scheduled task",()=>{var j=Job();string n=Jobs.Register(j);status.Text=L.F("Task created: {0}",n);}));buttons.Controls.Add(UI.Button("Run now",RunNow));buttons.Controls.Add(UI.Button("Open Windows Task Scheduler",()=>UI.Shell("taskschd.msc")));buttons.Controls.Add(UI.Button("Close",Close));buttons.Controls.Add(new Label{Text=L.T("Scheduled tasks run while this Windows user is signed in."),AutoSize=true,Width=700});status=new Label{Dock=DockStyle.Bottom,Height=30,Padding=new Padding(8),Text=L.T("Ready")};Controls.Add(table);Controls.Add(buttons);Controls.Add(status);Palette.Apply(this);
  }
  private ComboBox Combo(string[] items){var c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};c.Items.AddRange(items);L.TranslateCombo(c);c.SelectedIndex=0;return c;}
  private ScheduledJob Job(){var ps=paths.Text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries);if(ps.Length==0||ps.Any(p=>!Directory.Exists(p)))throw new DirectoryNotFoundException(L.T("Please enter a valid folder path."));if(string.IsNullOrWhiteSpace(output.Text))throw new ArgumentException(L.T("Output folder"));if(email.Checked&&(string.IsNullOrWhiteSpace(settings.MailTo)||string.IsNullOrWhiteSpace(settings.SmtpHost)))throw new InvalidOperationException(L.Chinese?"请先在选项中配置邮件。":"Configure email in Options first.");return new ScheduledJob{Name=name.Text,Paths=string.Join("|",ps),Output=Path.GetFullPath(output.Text),Report=(string)report.SelectedItem,Format=(string)format.SelectedItem,Frequency=(string)frequency.SelectedItem,Start=start.Value,Email=email.Checked,Options=UI.Clone(settings.Scan)};}
  private async void RunNow(){try{var j=Job();status.Text=L.T("Scanning...");await Task.Run(()=>Jobs.Run(j));if(!IsDisposed)status.Text=L.T("Operation completed.");}catch(Exception ex){if(!IsDisposed)UI.Error(ex);}}
 }
 public static class Dialogs {
  public static void Rows(IWin32Window owner,string title,List<ReportRow> rows){using(var f=UI.Dialog(title,1100,720)){var grid=new ReportGrid(false);grid.Columns["Full Path"].Visible=true;grid.Columns["Information"].Visible=true;grid.SetData(rows);var bar=new ToolStrip{Dock=DockStyle.Top,GripStyle=ToolStripGripStyle.Hidden};bar.Items.Add(UI.Tool("Export","export",()=>UI.Export(f,L.T(title),grid.Data)));bar.Items.Add(UI.Tool("Print","print",()=>UI.Print(f,L.T(title),grid.Data)));bar.Items.Add(UI.Tool("Clipboard","file",()=>Clipboard.SetText(Exporter.ToCsv(grid.Data,true))));bar.Items.Add(UI.Tool("Columns","panel",()=>grid.ColumnMenu(grid,new Point(10,10))));f.Controls.Add(grid);f.Controls.Add(bar);Palette.Apply(f);f.ShowDialog(owner);}}
  public static void Trends(IWin32Window owner){using(var f=UI.Dialog("Trend Analyzer",1150,760)){var files=new List<string>();var list=new ListBox{Dock=DockStyle.Top,Height=110};var grid=new ReportGrid(false);grid.Columns["Full Path"].Visible=true;grid.Columns["Information"].Visible=true;var bar=new ToolStrip{Dock=DockStyle.Top,GripStyle=ToolStripGripStyle.Hidden};bar.Items.Add(UI.Tool("Add snapshots","load",()=>{using(var d=new OpenFileDialog{Filter="FolderScope snapshot (*.fsscan)|*.fsscan",Multiselect=true})if(d.ShowDialog(f)==DialogResult.OK)foreach(string p in d.FileNames)if(!files.Contains(p)){files.Add(p);list.Items.Add(p);}}));bar.Items.Add(UI.Tool("Remove","delete",()=>{if(list.SelectedIndex>=0){files.RemoveAt(list.SelectedIndex);list.Items.RemoveAt(list.SelectedIndex);}}));bar.Items.Add(UI.Tool("Analyze","trend",()=>{if(files.Count<2)throw new InvalidOperationException(L.T("Choose at least two snapshots."));var data=files.Select(Snapshot.Load).OrderBy(s=>s.Captured).ToList();var rows=new List<ReportRow>();foreach(Snapshot s in data){long size=s.Roots.Sum(p=>s.Index[p].Size),n=s.Entries.LongCount(e=>!e.Folder);rows.Add(new ReportRow{Name=Util.Date(s.Captured),Size=size,Count=n,Modified=s.Captured,Extra=string.Join("; ",s.Roots)});}var changes=Reports.Compare(data.First(),data.Last());rows.AddRange(changes);grid.SetData(rows);}));bar.Items.Add(UI.Tool("Export","export",()=>UI.Export(f,f.Text,grid.Data)));f.Controls.Add(grid);f.Controls.Add(list);f.Controls.Add(bar);Palette.Apply(f);f.ShowDialog(owner);}}
  public static void History(IWin32Window owner){using(var f=UI.Dialog("Disk History",1050,700)){var grid=new ReportGrid(false);Action reload=()=>{var h=DiskHistory.Load();grid.SetData(h.Points.OrderByDescending(p=>p.Time).Select(p=>new ReportRow{Name=p.Root,Size=p.Total-p.Free,Allocated=p.Free,Modified=p.Time,Percent=p.Total==0?0:(p.Total-p.Free)*100.0/p.Total,Extra=L.T("Total")+": "+Util.Size(p.Total)}).ToList());};var bar=new ToolStrip{Dock=DockStyle.Top,GripStyle=ToolStripGripStyle.Hidden};bar.Items.Add(UI.Tool("Refresh history","refresh",()=>{var h=DiskHistory.Load();h.Record();reload();}));bar.Items.Add(UI.Tool("Export","export",()=>UI.Export(f,f.Text,grid.Data)));grid.Columns["Size"].HeaderText=L.T("Used");grid.Columns["Size on Disk"].HeaderText=L.T("Free");f.Controls.Add(grid);f.Controls.Add(bar);reload();Palette.Apply(f);f.ShowDialog(owner);}}
  [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]private struct ShareInfo{[MarshalAs(UnmanagedType.LPWStr)]public string Name;public uint Type;[MarshalAs(UnmanagedType.LPWStr)]public string Remark;}
  [DllImport("Netapi32.dll",CharSet=CharSet.Unicode)]private static extern int NetShareEnum(string server,int level,out IntPtr buffer,int preferred,out int read,out int total,ref int resume);
  [DllImport("Netapi32.dll")]private static extern int NetApiBufferFree(IntPtr buffer);
  public static void Network(IWin32Window owner,Action<string> scan){using(var f=UI.Dialog("Network Shares",900,640)){var host=new TextBox{Dock=DockStyle.Top,Height=30,Text=Environment.MachineName};var grid=new ReportGrid(false);grid.Columns["Full Path"].Visible=true;var bar=new ToolStrip{Dock=DockStyle.Top,GripStyle=ToolStripGripStyle.Hidden};bar.Items.Add(UI.Tool("Discover","search",async ()=>{try{string server=host.Text.Trim().TrimStart('\\');if(string.IsNullOrWhiteSpace(server)||server.Contains("\\")||server.Contains("/"))throw new ArgumentException(L.T("Server (name or IP)"));var rows=await Task.Run(()=>Shares(server));if(!f.IsDisposed)grid.SetData(rows);}catch(Exception ex){if(!f.IsDisposed)UI.Error(ex);}}));bar.Items.Add(UI.Tool("Analyze selected","play",()=>{var r=grid.Selected().FirstOrDefault();if(r!=null){f.Close();scan(r.Path);}}));var label=new Label{Text=L.T("Server (name or IP)"),Dock=DockStyle.Top,Height=27};f.Controls.Add(grid);f.Controls.Add(bar);f.Controls.Add(host);f.Controls.Add(label);Palette.Apply(f);f.ShowDialog(owner);}}
  private static List<ReportRow> Shares(string server){var rows=new List<ReportRow>();int resume=0,status;do{IntPtr p;int read,total;status=NetShareEnum(@"\\"+server,1,out p,-1,out read,out total,ref resume);try{if(status!=0&&status!=234)throw new System.ComponentModel.Win32Exception(status);int size=Marshal.SizeOf(typeof(ShareInfo));for(int i=0;i<read;i++){var s=(ShareInfo)Marshal.PtrToStructure(IntPtr.Add(p,i*size),typeof(ShareInfo));if((s.Type&255)==0)rows.Add(new ReportRow{Name=s.Name,Path=@"\\"+server+@"\"+s.Name,Extra=s.Remark});}}finally{if(p!=IntPtr.Zero)NetApiBufferFree(p);}}while(status==234);return rows;}
 }
}
